using System.Windows;using System.Windows.Controls;using System.Windows.Data;using System.Windows.Media;using PhotoBooth.Color.D3D11;using PhotoBooth.Customer.UI.ViewModels;namespace PhotoBooth.Customer.UI.Views { public partial class WaitingView:UserControl { public WaitingView(){InitializeComponent();Loaded+=(s,e)=>BindSize(this);}void OnGpuLiveColorFailed(object sender,LiveColorFailedEventArgs e){(DataContext as WaitingViewModel)?.DisableGpuLiveColor(e.Error);}static void BindSize(DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var surface=child as LiveColorSurface;if(surface!=null){BindingOperations.SetBinding(surface,LiveColorSurface.FrameWidthProperty,new Binding(nameof(WaitingViewModel.LiveFrameWidth)));BindingOperations.SetBinding(surface,LiveColorSurface.FrameHeightProperty,new Binding(nameof(WaitingViewModel.LiveFrameHeight)));}BindSize(child);}} } }
